void setupRackTests(){
    using M=Metropolix;static_assert(M::ENC_CONFIRM==728 && M::EXT_CLOCK_DIV==734 && M::RUN_ON_BOOT==735 && M::FORMAT22_NUM_PARAMS==736 && M::FORMAT8_PARAMS==492,"setup globals append without changing preset or cable IDs");
    Module::ProcessArgs args;args.sampleRate=48000;args.sampleTime=1.f/48000;
    auto frames=[&](M& m,int n){for(int f=0;f<n;++f){args.frame++;m.process(args);}};
    for(int boot=0;boot<3;++boot)for(int run=0;run<2;++run){auto m=std::unique_ptr<M>(new M);m->params[M::RUN].setValue(run);m->params[M::RUN_ON_BOOT].setValue(boot);m->params[M::CV_OUT_DELAY].setValue(21);m->params[M::EXT_CLOCK_DIV].setValue(6);m->uiDraftParam=M::TEMPO;m->uiDraftValue=150;json_t* params=m->paramsToJson(),*data=m->dataToJson();auto copy=std::unique_ptr<M>(new M);copy->paramsFromJson(params);copy->dataFromJson(data);require(copy->integer(M::RUN)==(boot==2?run:boot),"boot Off/On/Patch respects explicit preference");require(copy->integer(M::CV_OUT_DELAY)==21 && copy->integer(M::EXT_CLOCK_DIV)==6 && copy->uiDraftParam<0,"global preferences persist but unconfirmed draft never does");json_object_set_new(data,"schemaVersion",json_integer(24));copy->paramsFromJson(params);copy->dataFromJson(data);require(copy->integer(M::RUN)==run && copy->integer(M::RUN_ON_BOOT)==2 && copy->integer(M::CV_OUT_DELAY)==0 && copy->integer(M::EXT_CLOCK_DIV)==1,"old patch retains transport and gains transparent setup defaults");json_decref(params);json_decref(data);}
    {auto m=std::unique_ptr<M>(new M);m->params[M::RUN].setValue(1);m->params[M::CLOCK_SOURCE].setValue(2);m->params[M::EXT_CLOCK_DIV].setValue(6);m->inputs[M::CLOCK_IN].channels=1;frames(*m,64);for(int p=0;p<25;++p){m->inputs[M::CLOCK_IN].setVoltage(5);frames(*m,1);m->inputs[M::CLOCK_IN].setVoltage(0);frames(*m,999);}require(m->sequencer.tracks[0].stage==4 && std::abs(m->displayBpm.load()-120)<.001,"24 ppq at 120 BPM divides into five real sixteenth-note edges");}
    for(int rate:{44100,48000,96000})for(int ms:{0,1,21}){auto immediate=std::unique_ptr<M>(new M),delayed=std::unique_ptr<M>(new M);Module::SampleRateChangeEvent e;e.sampleRate=rate;e.sampleTime=1.f/rate;immediate->onSampleRateChange(e);delayed->onSampleRateChange(e);args.sampleRate=rate;args.sampleTime=1.f/rate;immediate->params[M::RUN].setValue(1);delayed->params[M::RUN].setValue(1);delayed->params[M::CV_OUT_DELAY].setValue(ms);immediate->tunerActive.store(true);delayed->tunerActive.store(true);immediate->params[M::TUNER_OCTAVE].setValue(3);delayed->params[M::TUNER_OCTAVE].setValue(3);int latency=int(std::round(rate*.001*ms));std::vector<std::array<float,7>> history;for(int f=0;f<latency+100;++f){immediate->process(args);delayed->process(args);std::array<float,7> values;for(int o=0;o<7;++o)values[o]=immediate->outputs[o].getVoltage();history.push_back(values);for(int o=0;o<7;++o)require(delayed->outputs[o].getVoltage()==(f<latency?0:history[f-latency][o]),"actual Rack pitch, gate, tuner, AUX and CLK ports share configured latency");}}
}
